{
  "contract": "BPYC",
  "closure": {
    "site_function": "swapBack",
    "site_call": ".addLiquidityETH",
    "functions": [
      "transfer",
      "transferFrom",
      "swapBack"
    ],
    "justification": "All functions that can modify exposed storage inSwap and swapThreshold must be included. 'transfer' and 'transferFrom' can invoke '_transferFrom', which updates '_rOwned' and '_totalProportion', indirectly affecting re-entrancy safety when combined with 'swapBack'."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "swapBack",
    "pre": {
      "name": "pre",
      "from_marker": "pre-swapBack",
      "to_marker": "call-risky"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "call-risky",
      "to_marker": "return-risky"
    },
    "post": {
      "name": "post",
      "from_marker": "return-risky",
      "to_marker": "post-swapBack"
    },
    "linearization_point": "return-risky"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "amount of '_rOwned' in transit during callback exposure",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__rOwned == _totalProportion + inFlight",
    "stable_formula": "_sum__rOwned == _totalProportion",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__rOwned == _totalProportion",
    "rule": "The 'conserve' invariant holds, ensuring '_sum__rOwned' balances with '_totalProportion' accounting for in-flight transfers during re-entrant calls."
  }
}
